# From the helper team's HelpProtocol instance
won = helper_hp.offer_help(request_id=request_id)
if won:
    print('Help request accepted -- start working on it')
else:
    print('Another team already claimed this request')

assignments = hp.auto_assign_idle_teams()
for a in assignments:
    print(f"Request {a['request_id']} assigned to {a['team']}")

# Send
msg_id = dc.send_direct(
    target_team='team-beta',
    msg_type='info',
    body={'event': 'data-ready', 'file': '/path/to/output.json'}
)

# Read (from the other team)
msgs = dc.read_direct(from_team='team-alpha')
for m in msgs:
    print(f"{m['team']}: {m['body']}")

available = dc.get_available_teams()
for t in available:
    print(f"{t['team']}: {t['status']}, channels: {t['current_channels']}")

item = ws.steal_work()
if item:
    print(f"Claimed: {item['title']} (id={item['id']})")
    # Do the work...
else:
    print('No work available')

